// Parse incoming VAPI request and validate
const body = $input.item.json.body;
const message = body?.message;
const toolWithToolCallList = message?.toolWithToolCallList || [];
const toolCall = toolWithToolCallList[0]?.toolCall;

if (!toolCall) {
  return [{
    json: {
      results: [{
        toolCallId: 'unknown',
        result: 'Błąd: Brak wywołania narzędzia w żądaniu'
      }]
    }
  }];
}

const args = toolCall.function.arguments;
const toolCallId = toolCall.id;
const requestType = args.Request;

// Barber calendars mapping - ZAKTUALIZUJ SWOJE CALENDAR IDS TUTAJ!
const barberCalendars = {
  "Ania": "cal-3b99b575@group.calendar.google.com",
  "Borys": "cal-a5a747c6@group.calendar.google.com",
  "Andrzej": "cal-5052a5da@group.calendar.google.com",
  "Bartek": "cal-1192ec64@group.calendar.google.com",
  "Magda": "cal-5465f5f8@group.calendar.google.com"
};

// Service durations (minutes)
const serviceDurations = {
  "Strzyżenie krótkie": 60,
  "Strzyżenie średnie": 60,
  "Strzyżenie długie": 90,
  "Maszynką": 30,
  "Broda": 30,
  "Strzyżenie brody": 30,
  "Golenie": 60,
  "Combo": 90,
  "Repigmentacja": 60,
  "Koloryzacja": 90
};

// Business hours configuration
const businessHours = {
  1: {start: '09:00', end: '19:00'},
  2: {start: '09:00', end: '19:00'},
  3: {start: '09:00', end: '21:00'},
  4: {start: '09:00', end: '21:00'},
  5: {start: '09:00', end: '21:00'},
  6: {start: '09:00', end: '21:00'},
  0: {start: '10:00', end: '19:00'}
};

// Normalize phone number to +48 format
function normalizePhone(phone) {
  if (!phone) return null;
  const digits = phone.replace(/\D/g, '');
  if (digits.length === 9) return '+48' + digits;
  if (digits.length === 11 && digits.startsWith('48')) return '+' + digits;
  if (digits.length === 12 && phone.startsWith('+48')) return phone;
  return null;
}

// Validate email format
function isValidEmail(email) {
  if (!email) return false;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

// Extract arguments
const barberName = args.Barber;
const service = args.Usluga;
const date = args.Data_Wizyty;
const time = args.Godzina_Wizyty;
const name = args.Imie_Nazwisko;
const email = args.Adres_Email;
const phone = args.Numer_Telefonu;
const starttime = args.starttime;
const endtime = args.endtime;

const calendarId = barberName ? barberCalendars[barberName] : null;
const duration = service ? serviceDurations[service] : 60;
const normalizedPhone = normalizePhone(phone);
const emailValid = isValidEmail(email);

const errors = [];

// Validation based on request type
if (requestType === 'Rezerwacja_Wizyty') {
  if (!name || name.split(' ').length < 2) errors.push('Imię i nazwisko wymagane (min 2 słowa)');
  if (!emailValid) errors.push('Nieprawidłowy format email');
  if (!normalizedPhone) errors.push('Nieprawidłowy numer telefonu (9 cyfr)');
  if (!barberName) errors.push('Barber wymagany');
  if (!service) errors.push('Usługa wymagana');
  if (!date) errors.push('Data wymagana');
  if (!time) errors.push('Godzina wymagana');
  if (!calendarId) errors.push('Nieznany barber');
}

if (requestType === 'Znajdz_Rezerwacje' || requestType === 'Anuluj_Rezerwacje') {
  if (!name) errors.push('Imię wymagane');
  if (!emailValid) errors.push('Nieprawidłowy format email');
}

if (requestType === 'Sprawdzenie_Dostepnosci') {
  if (!starttime || !endtime) errors.push('starttime i endtime wymagane');
}

return [{
  json: {
    requestType,
    barberName,
    calendarId,
    service,
    duration,
    date,
    time,
    name,
    email,
    emailValid,
    phone: normalizedPhone,
    starttime,
    endtime,
    toolCallId,
    errors,
    hasErrors: errors.length > 0,
    allBarbers: Object.keys(barberCalendars),
    barberCalendars,
    businessHours,
    customerNumber: body.message?.call?.customer?.number,
    callId: body.message?.call?.id,
    body
  }
}];

const errors = $input.item.json.errors || [];
const toolCallId = $input.item.json.toolCallId || 'unknown';

return [{
  json: {
    results: [{
      toolCallId,
      result: `Błąd walidacji: ${errors.join(', ')}`
    }]
  }
}];

// Prepare availability check
const {starttime, endtime, barberName, calendarId, toolCallId} = $input.item.json;

if (!starttime || !endtime) {
  return [{
    json: {
      results: [{
        toolCallId,
        result: "Proszę podać starttime i endtime w formacie ISO 8601"
      }]
    }
  }];
}

// Parse dates
const startDate = new Date(starttime);
const endDate = new Date(endtime);

if (isNaN(startDate) || isNaN(endDate)) {
  return [{
    json: {
      results: [{
        toolCallId,
        result: "Nieprawidłowy format daty. Użyj ISO 8601"
      }]
    }
  }];
}

// Jeśli brak barbera, użyj kalendarza właściciela
const ownerCalendarId = "test@example.com";
const finalCalendarId = calendarId || ownerCalendarId;

return [{
  json: {
    calendarId: finalCalendarId,
    barberName: barberName || 'dowolny barber',
    starttime,
    endtime,
    toolCallId
  }
}];

const events = $input.all();
const prepare = $('Prepare Availability Check').first().json;
const { barberName, toolCallId } = prepare;

const validEvents = events.filter(e => e.json.id);

const resultText = validEvents.length > 0
  ? `Zajęte. ${barberName} niedostępny w tym czasie.`
  : `Wolne! ${barberName} dostępny w tym czasie.`;

// Zwracamy czysty obiekt, bez tablicy zewnętrznej
return {
  results: [
    {
      toolCallId,
      result: resultText
    }
  ]
};

// Prepare booking data
const {date, time, duration, barberName, calendarId, service, name, email, phone, toolCallId} = $input.item.json;

if (!date || !time) {
  return [{
    json: {
      results: [{
        toolCallId,
        result: "Data i godzina wymagane"
      }]
    }
  }];
}

// Build ISO datetime strings for Europe/Warsaw timezone
const startDateTime = new Date(`${date}T${time}:00+01:00`);
const endDateTime = new Date(startDateTime.getTime() + duration * 60000);

const startISO = startDateTime.toISOString();
const endISO = endDateTime.toISOString();

return [{
  json: {
    calendarId,
    barberName,
    service,
    date,
    time,
    startISO,
    endISO,
    duration,
    name,
    email,
    phone,
    toolCallId,
    summary: `${service} - ${name}`,
    description: `Rezerwacja VAPI\nKlient: ${name}\nEmail: ${email}\nTelefon: ${phone}\nUsługa: ${service}`
  }
}];

const events = $input.all();
const prepare = $('Prepare Booking Data').first().json;
const { time, date, service, name, barberName, toolCallId } = prepare

return [{
  json: {
    results: [{
      toolCallId,
      result: `Gotowe! ${name}, ${service} u ${barberName}, ${date} o ${time}. Potwierdzenie wysłane na email.`
    }]
  }
}];

// Prepare find booking - split by all calendars
const {name, email, toolCallId, barberCalendars} = $input.item.json;

const calendars = Object.entries(barberCalendars).map(([barber, calId]) => ({
  barber,
  calendarId: calId,
  name,
  email,
  toolCallId
}));

return calendars.map(cal => ({json: cal}));

const prepare = $('Prepare Find Booking').first().json;
const { toolCallId } = prepare
const allEvents = $input.all();
const validEvents = allEvents.filter(e => e.json.id && e.json.summary);

if (validEvents.length === 0) {
  return [{
    json: {
      results: [{
        toolCallId,
        result: "Nie znaleziono żadnej rezerwacji"
      }]
    }
  }];
}

const booking = validEvents[0].json;
const summary = booking.summary;
const startTime = booking.start?.dateTime || booking.start?.date;
const formattedTime = new Date(startTime).toLocaleString('pl-PL', {
  timeZone: 'Europe/Warsaw',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

return [{
  json: {
    results: [{
      toolCallId,
      result: `Znaleziono rezerwację: ${summary}, ${formattedTime}`
    }]
  }
}];

// Prepare cancellation - split by all calendars
const {name, email, toolCallId, barberCalendars} = $input.item.json;

const calendars = Object.entries(barberCalendars).map(([barber, calId]) => ({
  barber,
  calendarId: calId,
  name,
  email,
  toolCallId
}));

return calendars.map(cal => ({json: cal}));

const prepare = $('Prepare Cancellation').first().json;
const { toolCallId } = prepare
const deleted = $input.all().length > 0;
const msg = deleted ? "Wizyta anulowana pomyślnie" : "Nie znaleziono wizyty do anulowania";

return [{
  json: {
    results: [{
      toolCallId,
      result: msg
    }]
  }
}];
